264	          "matches_verse": true
265	        }
266	      }
267	    },
268	    {
269	      "verse_id": "5.15.12",
270	      "sarga": 15,
271	      "verse": "12",
272	      "ambiguous_marker": false,
273	      "sanskrit_iast": "ativṛttam ivācintyaṃ divyaṃ ramyaśriyāyutam । dvitīyam iva cākāśaṃ puṣpajyotirgaṇāyutam ॥12॥",
274	      "leonov_ru": "Даже превосходя [их] – невообразимая, дивная, прекрасная, наделенная сиянием, Подобная второму небу с цветами вместо звезд.",
275	      "commentary": {
276	        "bhusana": "द्वितीयमिव चाकाशं पुष्पज्योतिर्गणायुतम् ।\n\nपुष्परत्नशतैश्चित्रं पञ्चमं सागरं यथा"
277	      },
278	      "pratika_check": {
279	        "bhusana": {
280	          "pratika_iast": "dvitiyaniva cakasan puspajyotirganayutan",
281	          "matches_verse": true
282	        }
283	      }
284	    },
285	    {
286	      "verse_id": "5.15.14",
287	      "sarga": 15,
288	      "verse": "14",
289	      "ambiguous_marker": false,
290	      "sanskrit_iast": "nānāninādair udyānaṃ ramyaṃ mṛgagaṇadvijaiḥ । anekagandhapravahaṃ puṇyagandhaṃ manoramam ॥14॥",
291	      "leonov_ru": "Прекрасный сад, оглашаемый голосами зверей и птиц, В котором распространялись разнообразные ароматы, душистый, чарующий,",
292	      "commentary": {
293	        "tilaka": "मृगादिभिः स्वीयैर्नानाविधैः शब्दै रम्यं कृतम् । एवंविशेषणकमुद्यानमशोकवनिकान्तर्गतं ददर्शेत्यनुकर्षः\nएवं मतेर्युक्तत्वमुपपादयति-- राज्यं वेति । त्रैलोक्यराज्यसीताप्राप्त्ययोः कतरदुत्कृष्टमिति विचारे आद्यं द्वितीयकोटिशतांशेन सादृश्यमपि नार्हतीत्यर्थः",
294	        "bhusana": "अनेकग्रन्धप्रवहं पुण्यगन्धं मनोरमम् ।\n\nशैलेन्द्रमिव गन्धाढ्यं द्वितीयं गन्धमादनम्"
295	      },
296	      "pratika_check": {
297	        "tilaka": {
298	          "pratika_iast": "nrgadibhih sviyairnanavidhaih sabdai ranyan",
299	          "matches_verse": true
300	        },
301	        "bhusana": {
302	          "pratika_iast": "anekagrandhapravahan punyagandhan nanoranan",
303	          "matches_verse": true
304	        }
305	      }
306	    },
307	    {
308	      "verse_id": "5.15.15",
309	      "sarga": 15,
310	      "verse": "15",
311	      "ambiguous_marker": false,
312	      "sanskrit_iast": "śailendram iva gandhāḍhyaṃ dvitīyaṃ gandhamādanam । aśokavanikāyāṃ tu tasyāṃ vānarapuṃgavaḥ ॥15॥",
313	      "leonov_ru": "Был он подобен второй горе Гандхамадане, богатой ароматами. В той роще ашоки бык среди обезьян",
314	      "commentary": {
315	        "tilaka": "शैलेन्द्रो हिमवान् । तस्यां पूर्ववर्णितायाम्\nयच्छेषतयैवं प्राशस्त्यं दर्शितं तस्य कालस्य दुरतिक्रमत्वमाह-- इयं सेति । राक्षसीवशमागता कालप्राबल्यादिति भावः । \"फलमत उपपत्तेः\" इति व्याससूत्रेणापि कालात्मनो भगवत एव कर्मफलप्रापणसामर्थ्यं दर्शितम्",
316	        "bhusana": "अशोकवनिकायां तु तस्यां वानरपुङ्गवः ।\n\nस ददर्शाविदूरस्थं चैत्यप्रासादमुच्छ्रितम्"
317	      },
318	      "pratika_check": {
