320	          "pratika_iast": "sailendro hinavan",
321	          "matches_verse": false,
322	          "content_containment": 0.111
323	        },
324	        "bhusana": {
325	          "pratika_iast": "asokavanikayan tu tasyan vanarapungavah",
326	          "matches_verse": true
327	        }
328	      }
329	    },
330	    {
331	      "verse_id": "5.15.16",
332	      "sarga": 15,
333	      "verse": "16",
334	      "ambiguous_marker": false,
335	      "sanskrit_iast": "sa dadarśāvidūrasthaṃ caityaprāsādam ūrjitam । madhye stambhasahasreṇa sthitaṃ kailāsapāṇḍuram ॥16॥",
336	      "leonov_ru": "Увидел расположенный неподалеку высокий дворец, подобный ступе, С расположенными посредине тысячами колонн, белый, словно гора Кайласа,",
337	      "commentary": {
338	        "tilaka": "तदुभयमप्यतिवृत्तमिवातिक्रम्ये स्थितम् । पुष्परूपज्योतिर्गणैरायुतम्",
339	        "bhusana": "मध्ये स्तम्भसहस्रेण स्थितं कैलासपाण्डुरम् ।\n\nप्रवालकृतसोपानं तप्तकाञ्जनवेदिकम्"
340	      },
341	      "pratika_check": {
342	        "tilaka": {
343	          "pratika_iast": "tadubhayanapyativrttanivatikranye sthitan",
344	          "matches_verse": true
