353	      "verse_id": "5.15.17",
354	      "sarga": 15,
355	      "verse": "17",
356	      "ambiguous_marker": false,
357	      "sanskrit_iast": "pravālakṛtasopānaṃ taptakāñcanavedikam । muṣṇantam iva cakṣūṃṣi dyotamānam iva śriyā ॥17॥",
358	      "leonov_ru": "С лестницами из кораллов, с возвышениями (или перилами) из расплавленного золота, Словно бы похищающий взгляды, словно бы сияющий роскошью,",
359	      "commentary": {
360	        "tilaka": "आधिक्यमेवोपपादयति-- इयमिति । अनेन कुलम्, भर्तृदृढव्रतेत्यनेन चारित्र्यातिशयः । मेदिनीं भित्त्वेत्यनेनायोनिजतया ऽमानुषदिव्यरूपत्वं दर्शितम् ।। 5.15.15,16 ।।\n\nआर्यशीलस्य पूज्यशीलस्य । अनेन महाकुलीनपाणिग्रहणं दर्शितम्",
361	        "bhusana": "मुष्णन्तमिव चक्षूंषि द्योतमानमिव श्रिया ।\n\nविमलं प्रांशुभावत्वादुल्लिखन्तमिवाम्बरम्\nप्रांशुभावत्वात् दीर्घस्वभावत्वात्"
362	      },
363	      "pratika_check": {
364	        "tilaka": {
365	          "pratika_iast": "adhikyanevopapadayati",
366	          "matches_verse": false,
367	          "content_containment": 0.0
368	        },
369	        "bhusana": {
370	          "pratika_iast": "nusnantaniva caksunsi dyotanananiva sriya",
371	          "matches_verse": true
372	        }
373	      }
