375	    {
376	      "verse_id": "5.15.18",
377	      "sarga": 15,
378	      "verse": "18",
379	      "ambiguous_marker": false,
380	      "sanskrit_iast": "nirmalaṃ prāṃśubhāvatvād ullikhantam ivāmbaram । tato malinasaṃvītāṃ rākṣasībhiḥ samāvṛtām ॥18॥",
381	      "leonov_ru": "Незапятнанный (чистый), благодаря своей высоте словно бы касающийся неба. И вот в грязной одежде, окруженную ракшаси,",
382	      "commentary": {
383	        "bhusana": "ततो मलिनसंवीतां राक्षसीभिः समावृताम् ।\n\nउपवासकृशां दीनां निःश्वसन्तीं पुनः पुनः\nमलिनसंवीतां मलिनवस्त्रेणावृताम्, मलिनैरङ्गैः संवीतां वा"
384	      },
385	      "pratika_check": {
386	        "bhusana": {
387	          "pratika_iast": "tato nalinasanvitan raksasibhih sanavrtan",
388	          "matches_verse": true
389	        }
390	      }
391	    },
392	    {
393	      "verse_id": "5.15.19",
394	      "sarga": 15,
395	      "verse": "19",
396	      "ambiguous_marker": false,
397	      "sanskrit_iast": "upavāsakṛśāṃ dīnāṃ niḥśvasāntīṃ punaḥ punaḥ । dadarśa śuklapakṣādau candrarekhām ivāmalām ॥19॥",
398	      "leonov_ru": "Исхудавшую от поста, печальную, то и дело вздыхающую Увидел [женщину], ясную, словно луна в начале светлой половины месяца.",
399	      "commentary": {
400	        "tilaka": "भर्तृस्नेहबलात्कृता बलात्प्रवर्तिता",
401	        "bhusana": "ददर्श शुक्लपक्षादौ चन्द्ररेखामिवामलाम् ।\n\nमन्दं प्रख्यायमानेन रूपेण रुचिरप्रभाम्\nशुक्लपक्षादावित्यनेन वर्धिष्णुत्वं द्योतितम् । मन्दं प्रख्यायमानेन इदं तदिति कथ़ञ्चित्प्रत्यभिज्ञायमानेन रूपेणोपलक्षिताम्"
402	      },
403	      "pratika_check": {
404	        "tilaka": {
405	          "pratika_iast": "bhartrsnehabalatkrta balatpravartita",
406	          "matches_verse": false,
407	          "content_containment": 0.0
408	        },
409	        "bhusana": {
410	          "pratika_iast": "dadarsa suklapaksadau candrarekhanivanalan",
411	          "matches_verse": true
412	        }
