415	    {
416	      "verse_id": "5.15.20",
417	      "sarga": 15,
418	      "verse": "20",
419	      "ambiguous_marker": false,
420	      "sanskrit_iast": "mandaprakhyāyamānena rūpeṇa ruciraprabhām । pinaddhāṃ dhūmajālena śikhām iva vibhāvasoḥ ॥20॥",
421	      "leonov_ru": "С трудноузнаваемым обликом, сияющую Подобно пламени огня, которое скрывают клубы дыма,",
422	      "commentary": {
423	        "tilaka": "चैत्यं वर्तुलाकारत्वाद्बुद्धायतनमिव प्रासादम् । स्तम्भसहस्रेणाधारभूतेन स्थितम् ।। 5.15.16,17 ।।\n\nप्रांशुभावत्वादुच्चस्वभावत्वात् । ततस्तद्दर्शनानन्तरम् । मलिनवासःसंवीतत्वादिविशेषणवतीं सीतां दूरादेव तन्मूलस्थां ददर्शेत्यनुकर्षः ।। 5.15.18,19 ।।\n\nमन्दप्रख्यायमानेन इदमिदमितीदं तदिति वा कथंचिदूह्यमानेन रूपेण स्वरूपेणोपलक्षिताम्\nभर्तृशुश्रूषणापरा । सन्नन्तात्स्वार्थे णिचि \"ण्यासश्रन्थ\" इति युच्",
424	        "bhusana": "पिनद्धां धूमजालेन शिखामिव विभावसोः ।\n\nपीतेनैकेन संवीतां क्लिष्टेनोत्तमवाससा\nपिनद्धामिति मलिनसंवीतत्वे उपमा । पिनद्धां बद्धाम् । उत्तरीयराहित्यं द्योतयितुमेकेनेत्युक्तिः"
425	      },
426	      "pratika_check": {
