440	      "verse_id": "5.15.21",
441	      "sarga": 15,
442	      "verse": "21",
443	      "ambiguous_marker": false,
444	      "sanskrit_iast": "pītenaikena saṃvītāṃ kliṣṭenottamavāsasā । sapaṅkām analaṃkārāṃ vipadmām iva padminīm ॥21॥",
445	      "leonov_ru": "Одетую в одно желтое платье, превосходное, [но] изношенное, Покрытую грязью, без украшений, подобную пруду, лишенному лотосов,",
446	      "commentary": {
447	        "tilaka": "क्लिष्टेन जीर्णेन पांसुष्वास्तरणेन वा क्लिष्टेन । सपङ्कां मलवच्छरीराम् । पद्मिनी लक्ष्मीर्लता च\nपूर्ववदेवाह-- सेयमिति । यातनां राक्षसीभिः संपाद्यमानतीव्रदुःखम् । अनर्थानामापदाम्",
448	        "bhusana": "सपङ्कामनलङ्कारां विपद्मामिव पद्मिनीम् ।\n\nव्रीडितां दुःखसंतप्तां परिम्लानां तपस्विनीम्\nसपङ्कां भूमेराविर्भवन्तीमिव स्थिताम् । अनलङ्कारां पङ्कं निवर्त्य अलङ्कुर्वतो ऽसन्निधानादलङ्काररहिताम् । रामागमने ऽप्ययमाश्रयो नोत्सादयितुमर्हतीत्येवं मन्यमानाम् । विपद्मामिव पद्मिनीं पद्मरहितां सरसीमिव स्थिताम् ।। 4.15.21 ।।\n\nग्रहेणाङ्गारकेणेव पीडितामिव रोहिणीम् ।\n\nअश्रुपर्णमुखीं दीनां कृशामनशनेन च",
449	        "siromani": "क्लिष्टेन जीर्णतया प्रतीतेन पीतेन एकेन उत्तमवाससा संवीताम् अनलङ्काराम् अलङ्कृतिरहिताम् अत एव विपद्मां पद्मरहितां पद्मिनीं सरसीमिव सपङ्कां मलिनाम्"
450	      },
451	      "pratika_check": {
452	        "tilaka": {
453	          "pratika_iast": "klistena jirnena pansusvastaranena va",
454	          "matches_verse": false,
455	          "content_containment": 0.125
456	        },
457	        "bhusana": {
458	          "pratika_iast": "sapankananalankaran vipadnaniva padninin",
459	          "matches_verse": true
460	        },
461	        "siromani": {
462	          "pratika_iast": "klistena jirnataya pratitena pitena",
463	          "matches_verse": true
