466	    },
467	    {
468	      "verse_id": "5.15.22",
469	      "sarga": 15,
470	      "verse": "22",
471	      "ambiguous_marker": false,
472	      "sanskrit_iast": "pīḍitāṃ duḥkhasaṃtaptāṃ parikṣīṇāṃ tapasvinīm । graheṇāṅgārakeṇeva pīḍitām iva rohiṇīm ॥22॥",
473	      "leonov_ru": "Измученную, истерзанную скорбью, исхудавшую страдалицу, Подобную [созвездию] Рохини, которое затмил Марс,",
